addPlus("maths",{g1:[
 TP("Ordering numbers to 100","",[
  pg("Numbers in Order","Read the big idea. Then fill in the missing numbers.","Know that numbers to 100 come in order, each one 1 more than the last.",
   CN(["input-numbers","straight-ruler"],"Numbers go in order, like steps on a ladder. Each number is 1 more than the one before it. On a number line, small numbers are on the left and big numbers are on the right.","In order"),
   F("",["21, 22, {{23}}, 24, {{25}}","56, {{57}}, 58, {{59}}, 60","87, 88, {{89}}, {{90}}, 91","95, {{96}}, 97, 98, {{99}}"],1)),
  pg("Before, After, Between","Write the missing number.","Find the number just before, just after or between.",
   NO("Just before means 1 less. Just after means 1 more. Between means the number in the middle."),
   F("",["Just before 40 is {{39}}.","Just after 67 is {{68}}.","Between 52 and 54 is {{53}}.","Just before 81 is {{80}}.","Just after 99 is {{100}}.","Between 29 and 31 is {{30}}."],2)),
  pg("Number Line Jumps","Fill in the missing numbers on each line.","Count forwards and backwards on a number line.",
   F("",["70, 71, 72, {{73}}, {{74}}, 75","48, 47, 46, {{45}}, {{44}}, 43","33, {{34}}, 35, {{36}}, 37, 38","64, 63, {{62}}, 61, {{60}}, 59"],1)),
  pg("Smallest to Biggest","Write the numbers in order, smallest first.","Order three numbers to 100 from smallest to biggest.",
   NO("Look at the tens first. The number with the fewest tens is the smallest. If the tens are the same, look at the ones."),
   F("",["45, 12, 31 → {{12}}, {{31}}, {{45}}","70, 7, 17 → {{7}}, {{17}}, {{70}}","58, 85, 50 → {{50}}, {{58}}, {{85}}","93, 39, 63 → {{39}}, {{63}}, {{93}}"],1)),
  pg("Biggest to Smallest","Write the numbers in order, biggest first.","Order three numbers to 100 from biggest to smallest.",
   F("",["26, 62, 46 → {{62}}, {{46}}, {{26}}","14, 41, 40 → {{41}}, {{40}}, {{14}}","99, 9, 90 → {{99}}, {{90}}, {{9}}","75, 57, 77 → {{77}}, {{75}}, {{57}}"],1)),
  pg("Circle the Number","Circle the right number.","Find the biggest or smallest number in a group.",
   CH("",[["The biggest number",["38","83","48"],1],["The smallest number",["61","16","66"],1],["The biggest number",["90","59","95"],2],["The smallest number",["24","42","20"],2],["The number between 70 and 80",["68","75","81"],1]])),
  pg("Count in Tens and Twos","Fill in the missing numbers.","Count in steps of 10 and 2 up to 100.",
   F("",["10, 20, 30, {{40}}, {{50}}, 60","35, 45, 55, {{65}}, {{75}}","2, 4, 6, {{8}}, {{10}}, 12","80, 82, 84, {{86}}, {{88}}","100, 90, 80, {{70}}, {{60}}"],1)),
  pg("Numbers Around Us","Look at each picture. Fill in the number.","Use before and after with numbers we see every day.",
   FP("",[["bus","Bus 47 has gone. The next bus is number {{48}}."],["house","Our house is number 36. Next door is number {{37}}."],["stadium","I sit in seat 59. My friend sits in seat {{60}}, just after me."],["calendar","Today is day 20. Yesterday was day {{19}}."]],2)),
  pg("Order Stories","Read and solve.","Use ordering to answer word problems.",
   WP("",["Ali has 45 marbles. Sara has 54 marbles. {{Sara}} has more.","Three children scored 62, 26 and 66 in a game. The top score is {{66}}.","Zain is on page 79 of his book. The next page is {{80}}.","Hira counts 91, 92, 93. The next number she says is {{94}}."])),
  pg("Exit Ticket","Show what you can do.","Check ordering numbers to 100.",
   F("",["Just after 49 is {{50}}.","Between 76 and 78 is {{77}}.","Smallest first: 54, 45, 50 → {{45}}, {{50}}, {{54}}","Count in tens: 30, 40, {{50}}, {{60}}"],1),
   WR("",["Write three numbers bigger than 80: ______  ______  ______","Write the numbers from 61 to 70: ______________________________"]))],
  "Numbers to 100 come in order. Each number is 1 more than the one before. To order numbers, look at the tens first, then the ones. Children also find the number before, after and between, and count in tens and twos.",
  ["Write 20 to 40 on cards, mix them up and put them back in order.","Say a number and ask for the number just before and just after.","Count in tens on your fingers up to 100."],
  ["Spot house numbers on your street and say which comes next.","Read page numbers in a book and find the page between two others."],
  "Children may put 9 after 70 because 9 looks big. Remind them: count the tens first, and 9 has no tens.",
  ["The Lift Game","Nani's building has floors numbered 1 to 20. Hamza pressed 12, then 7, then 15. 'Which floor do we reach first going up?' asked Nani. 'Seven!' said Hamza. Ask: Which floor did they reach last?"])
]});

addPlus("science",{g1:[
 TP("Healthy habits and germs","",[
  pg("What Are Germs?","Read the big idea. Then circle true or false.","Know that germs are tiny living things that can make us ill.",
   CN(["microbe","soap","hand-with-fingers-splayed"],"Germs are tiny living things. They are too small to see. Some germs can make us ill. Washing our hands with soap and water helps get rid of germs.","Germs"),
   CH("",[["Germs are too small to see.",0],["Some germs can make us ill.",0],["Soap and water help wash germs away.",0],["Germs are as big as a cat.",1]],TF)),
  pg("Good Habits","Look at each picture. Write the word.","Name habits that keep us healthy.",BK(["soap","teeth","sleep","water","sneeze","play"]),
   FP("",[["soap","Wash your hands with {{soap}}."],["toothbrush","Brush your {{teeth}} two times a day."],["bed","Get plenty of {{sleep}}."],["potable-water","Drink clean {{water}}."],["roll-of-paper","Cover your {{sneeze}} with a tissue."],["person-running","Run and {{play}} outside."]],2)),
  pg("Washing My Hands","Fill in the missing words.","Know the steps for washing hands well.",BK(["wet","soap","rub","rinse","dry"]),
   CY("",[["droplet","{{wet}} your hands"],["soap","Put on {{soap}}"],["bubbles","{{rub}} for 20 seconds"],["shower","{{rinse}} with water"],["roll-of-paper","{{dry}} with a clean towel"]])),
  pg("Healthy or Not?","Look at each picture. Circle healthy or not healthy.","Tell healthy habits from unhealthy ones.",
   CP("",[["toothbrush","Brushing teeth before bed",0],["candy","Eating sweets all day",1],["soap","Washing hands before eating",0],["sneezing-face","Sneezing on a friend",1],["bed","Going to sleep early",0]],["healthy","not healthy"])),
  pg("When Do We Wash?","Circle yes or no.","Know when to wash our hands.",
   CH("",[["Before we eat",0],["After using the toilet",0],["After playing outside",0],["After stroking a pet",0],["Only once a week",1]],YN)),
  pg("The Glitter Test","Read about the test. Circle the right answer.","Read a simple experiment that shows how germs spread.",
   PA("Miss Sadia put a little glitter on Ali's hand. She said, 'This glitter is like germs.' Ali shook hands with Zain. Then Zain touched a pencil. Soon there was glitter on Zain's hand and on the pencil too! Ali washed with water only, and some glitter stayed. Then he used soap, and the glitter came off."),
   CH("",[["What was the glitter like?",["germs","sweets"],0],["How did glitter get on Zain's hand?",["a handshake","the rain"],0],["What took the glitter off best?",["water only","soap and water"],1]])),
  pg("Why Do We Do It?","Match each habit to why it helps.","Know why healthy habits matter.",
   MA("Write the letter in the box.",["washing hands","brushing teeth","sleeping well","covering a sneeze","drinking water"],["takes germs off our hands","keeps teeth strong and clean","gives our body rest","stops germs flying to others","helps our body work well"])),
  pg("Healthy Sums","Read and solve.","Use maths with healthy habits.",
   WP("",["Zain brushes his teeth 2 times a day. In 5 days he brushes {{10}} times.","Ali drinks 2 glasses of water in the morning, 3 in the afternoon and 2 at night. That is {{7}} glasses.","Ammi has 12 bars of soap. She puts 4 in the bathrooms. {{8}} are left.","Hira sleeps from 8 at night to 6 in the morning. She sleeps {{10}} hours."])),
  pg("Spread or Stop?","Write each one under the right heading.","Sort what spreads germs from what stops them.",
   SO("",["spreads germs","stops germs"],["sneezing into the air","washing with soap","sharing a used spoon","using a tissue","dirty nails","clean nails"],[0,1,0,1,0,1])),
  pg("My Healthy Week","Finish the sentences. Then draw.","Plan your own healthy habits.",
   WR("",["I wash my hands before ______________________.","I brush my teeth ______ times a day.","My healthy habit this week is ______________________."]),DR("Me washing my hands",220))],
  "Germs are tiny living things, too small to see, and some can make us ill. Good habits keep germs away: washing hands with soap, brushing teeth, covering sneezes, drinking clean water, sleeping well and playing outside.",
  ["Wash hands together and sing a short song that lasts about 20 seconds.","Put a tissue box where your child can reach it.","Make a simple chart of morning and night habits."],
  ["Try the glitter test at home with a little flour or glitter.","Tick a habit chart for brushing teeth every day for a week."],
  "Children may think water alone is enough. Show that soap is what lifts dirt and germs off the skin.",
  ["Bunty the Bubble","Bunty was a soap bubble who lived by the sink. Every day before lunch, Rayan came to wash his hands. Bunty helped scrub away the germs, and Rayan dried his hands clean. Ask: When did Rayan wash his hands?"])
]});

